function exploreHeaderStep(t){tab=t;render();document.querySelector('#main .experience')?.scrollIntoView({behavior:'smooth',block:'start'})}
const renderBeforeIntroductions=render;
render=function(){renderBeforeIntroductions();if(current<0)return;const p=productStories[current];document.querySelector('#main').insertAdjacentHTML('afterbegin',`<section class="product-story" aria-label="About ${esc(toolsList[current][0])}"><div class="story-main"><div class="story-eyebrow"><span class="story-icon">${icon(productIcons[current])}</span><span>NINE-67 <i>/</i> ${esc(toolsList[current][0])}</span></div><h1>${esc(p.title)}</h1><p class="story-description">${esc(p.desc)}</p><div class="story-audience"><span>BUILT FOR</span>${esc(p.audience)}</div></div><aside class="story-result"><div class="story-panel-label">THE WORKFLOW, AT A GLANCE</div><div class="story-io"><span class="story-dot"></span><div><small>START WITH</small><strong>${esc(p.input)}</strong></div></div><div class="story-connector"></div><div class="story-io output"><span class="story-dot">${icon('check')}</span><div><small>WALK AWAY WITH</small><strong>${esc(p.output)}</strong></div></div><p class="story-value">${esc(p.value)}</p>${p.note?`<p class="story-note">${esc(p.note)}</p>`:''}</aside><div class="story-steps"><div class="story-step-label">EXPLORE THE<br>WORKFLOW <span>Click a step to open it</span></div>${p.steps.map((s,i)=>`<button class="story-step ${tab===s[2]?'active':''}" onclick="exploreHeaderStep(${s[2]})"><span class="story-step-number">0${i+1}</span><span class="story-step-copy"><b>${esc(s[0])}</b><small>${esc(s[1])}</small></span><span class="story-step-arrow">↗</span></button>`).join('')}</div></section>`)};
render();
